from core.rules import RuleMachine


class EqualTopFrontierMerge:
    """Merge equal top groups across frontier stacks by placing a top container onto another stack with the same top group."""

    name = "equal_top_frontier_merge"

    def __init__(self, require_unsorted_destination=True, prefer_taller_destination=True):
        self.require_unsorted_destination = require_unsorted_destination
        self.prefer_taller_destination = prefer_taller_destination

    def _is_frontier_top(self, layout, s):
        h = layout.h(s)
        return h > 0 and layout.sorted_n[s] < h

    def allowed(self, partial, memory, candidates):
        chosen = []
        for a in candidates:
            so = a.so
            sd = a.sd

            if partial.h(so) == 0 or partial.e(sd) == 0:
                continue

            gs = partial.g(so)
            gd = partial.g(sd)

            if gs != gd:
                continue

            if not self._is_frontier_top(partial, so):
                continue

            if self.require_unsorted_destination and partial.is_sorted_stack(sd):
                continue

            if partial.after(so, sd) in partial.visited if partial.visited is not None else False:
                continue

            chosen.append(a)

        if not chosen:
            return []

        def key(a):
            so = a.so
            sd = a.sd
            src_h = partial.h(so)
            dst_h = partial.h(sd)
            src_unsorted = partial.h(so) - partial.sorted_n[so]
            dst_unsorted = partial.h(sd) - partial.sorted_n[sd]
            if self.prefer_taller_destination:
                return (-dst_h, src_h, -dst_unsorted, src_unsorted, so, sd)
            return (src_h, -dst_h, -dst_unsorted, src_unsorted, so, sd)

        chosen.sort(key=key)
        return chosen


def build_component(problem, require_unsorted_destination=True, prefer_taller_destination=True, **params):
    rule = EqualTopFrontierMerge(
        require_unsorted_destination=require_unsorted_destination,
        prefer_taller_destination=prefer_taller_destination,
    )
    return RuleMachine(problem, [rule])
